class Solution {
public:
    vector<int> permute(int n, long long k) {
        const long long LIM = 1000000000000000LL;
        vector<long long> fact(n + 1); fact[0] = 1;
        for (int i = 1; i <= n; i++)
            fact[i] = (fact[i - 1] > LIM / i) ? LIM + 1 : fact[i - 1] * i;
        auto sat = [&](long long a, long long b) {
            return (a > LIM || b > LIM || a > LIM / b) ? LIM + 1 : a * b;
        };
        vector<int> odds, evens;
        for (int x = 1; x <= n; x++) (x % 2 ? odds : evens).push_back(x);
        k--;
        vector<int> res; int prev = 0;
        for (int pos = 0; pos < n; pos++) {
            bool placed = false;
            for (int v = 1; v <= n && !placed; v++) {
                if (prev && v % 2 == prev % 2) continue;
                bool isO = v % 2 == 1;
                auto& lst = isO ? odds : evens;
                if (find(lst.begin(), lst.end(), v) == lst.end()) continue;
                long long no = odds.size() - isO, ne = evens.size() - (!isO);
                int tot = no + ne;
                long long ho = (!isO) ? (tot + 1) / 2 : tot / 2;
                if (no != ho) continue;
                long long w = sat(fact[no], fact[ne]);
                if (k >= w) { k -= w; continue; }
                res.push_back(v);
                lst.erase(find(lst.begin(), lst.end(), v));
                prev = v; placed = true;
            }
            if (!placed) return {};
        }
        return res;
    }
};

