class Solution {
    public int[] permute(int n, long k) {
        final long LIM = 1_000_000_000_000_000L;
        long[] fact = new long[n + 1]; fact[0] = 1;
        for (int i = 1; i <= n; i++)
            fact[i] = (fact[i - 1] > LIM / i) ? LIM + 1 : fact[i - 1] * i;
        List<Integer> odds = new ArrayList<>(), evens = new ArrayList<>();
        for (int x = 1; x <= n; x++) (x % 2 == 1 ? odds : evens).add(x);
        k--;
        int[] res = new int[n]; int prev = 0;
        for (int pos = 0; pos < n; pos++) {
            boolean placed = false;
            for (int v = 1; v <= n && !placed; v++) {
                if (prev != 0 && v % 2 == prev % 2) continue;
                boolean isO = v % 2 == 1;
                List<Integer> lst = isO ? odds : evens;
                if (!lst.contains(v)) continue;
                long no = odds.size() - (isO ? 1 : 0), ne = evens.size() - (isO ? 0 : 1);
                int tot = (int) (no + ne);
                long ho = !isO ? (tot + 1) / 2 : tot / 2;
                if (no != ho) continue;
                long a = fact[(int) no], b = fact[(int) ne];
                long w = (a > LIM || b > LIM || a > LIM / b) ? LIM + 1 : a * b;
                if (k >= w) { k -= w; continue; }
                res[pos] = v;
                lst.remove(Integer.valueOf(v));
                prev = v; placed = true;
            }
            if (!placed) return new int[0];
        }
        return res;
    }
}

