var permute = function(n, k) {
    const LIM = 1e15;
    const fact = [1];
    for (let i = 1; i <= n; i++)
        fact[i] = fact[i - 1] > LIM / i ? LIM + 1 : fact[i - 1] * i;
    const odds = [], evens = [];
    for (let x = 1; x <= n; x++) (x % 2 ? odds : evens).push(x);
    k--;
    const res = [];
    let prev = 0;
    for (let pos = 0; pos < n; pos++) {
        let placed = false;
        for (let v = 1; v <= n && !placed; v++) {
            if (prev && v % 2 === prev % 2) continue;
            const isO = v % 2 === 1;
            const lst = isO ? odds : evens;
            if (!lst.includes(v)) continue;
            const no = odds.length - (isO ? 1 : 0), ne = evens.length - (isO ? 0 : 1);
            const tot = no + ne;
            const ho = !isO ? Math.ceil(tot / 2) : Math.floor(tot / 2);
            if (no !== ho) continue;
            const a = fact[no], b = fact[ne];
            const w = (a > LIM || b > LIM || a > LIM / b) ? LIM + 1 : a * b;
            if (k >= w) { k -= w; continue; }
            res.push(v);
            lst.splice(lst.indexOf(v), 1);
            prev = v; placed = true;
        }
        if (!placed) return [];
    }
    return res;
};
